{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large glycosylated polyketide with multiple sugar and polar groups, achieved only a 0.12 CSF:plasma ratio in monkeys and little brain uptake, demonstrating poor CNS penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Erythromycin, a glycosylated macrolide, reached CSF concentrations of only 0.1-2.5 µg/ml versus serum peaks of 8-12 µg/ml even in meningitis, showing that polar glycosidic drugs have limited blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a cardiac glycoside, exhibited a very low CSF/plasma ratio of 0.01-0.03 in dogs, indicating that glycoside-containing natural products generally do not easily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Orientin, a polar glycoside, showed low brain levels after intravenous administration in rats due to high polarity, supporting that the multiple polar sugar and hydroxyl groups in the query molecule limit CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Doxorubicin is a polar anthracycline glycoside and known P-glycoprotein substrate; the direct evidence from related glycosides consistently shows poor brain and CSF penetration. Although cyclosporine co-treatment may partially inhibit efflux, it is unlikely to convert doxorubicin into a molecule with meaningful CNS access.",
  "evidence_gaps": [
    "No direct doxorubicin-plus-cyclosporine brain or CSF exposure measurement is present in the evidence set.",
    "The magnitude of P-glycoprotein inhibition by cyclosporine on doxorubicin brain concentrations is not quantified here."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

